// Some portions generated by Codex
package org.eclipse.rdf4j.tools.serverboot;

import static org.assertj.core.api.Assertions.assertThat;

import org.apache.catalina.core.StandardContext;
import org.junit.jupiter.api.Test;

class WorkbenchLegalResourcesTest {

	@Test
	void noticesAreRevalidatedAfterAnUpgrade() {
		var registration = new Rdf4jServerWorkbenchApplication().revalidatedAssetFilter();
		assertThat(registration.getUrlPatterns()).contains("/rdf4j-workbench/legal/*");
		assertThat(registration.getInitParameters()).containsEntry("Cache-Control", "0");
	}

	@Test
	void projectNoticeIsDisplayedAsPlainText() throws Exception {
		try (WebappResourceExtractor extractor = new WebappResourceExtractor()) {
			var factory = new Rdf4jServerWorkbenchApplication().tomcatFactory(extractor);
			var context = new StandardContext();
			factory.getContextCustomizers().forEach(customizer -> customizer.customize(context));

			assertThat(context.findMimeMapping("md")).isEqualTo("text/plain");
			assertThat(extractor.getServerDocBase().resolve("rdf4j-workbench/legal/NOTICE.md")).isRegularFile();
			assertThat(extractor.getServerDocBase().resolve("rdf4j-workbench/legal/third-party-notices.html"))
					.isRegularFile();
		}
	}
}
